func (a *aggregator) finish() []Agent {
	for i := range a.agents {
		a.agents[i].Tokens, a.agents[i].Models = Tokens{}, nil
		a.agents[i].Messages, a.agents[i].PartialMessages = 0, 0
	}
	for _, key := range a.order {
		e := a.entries[key]
		ag := &a.agents[e.agent]
		ag.Tokens = ag.Tokens.Add(e.tokens)
		ag.Messages++
		if e.stopNull {
			ag.PartialMessages++
		}
		ag.addModel(e.model)
	}
	return a.agents
}

// addModel appends model unless it is empty or already listed.
func (ag *Agent) addModel(model string) {
	if model == "" {
		return
	}
	for _, m := range ag.Models {
		if m == model {
			return
		}
	}
	ag.Models = append(ag.Models, model)
}
package agentusage

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const (
	transcriptExt = ".jsonl"
	metaExt       = ".meta.json"
	agentPrefix   = "agent-"
	subagentsDir  = "subagents"
)

// SubAgentFiles locates one sub-agent's files; Meta is "" if absent.
type SubAgentFiles struct{ ID, Transcript, Meta string }

// SessionFiles locates a session's transcripts.
type SessionFiles struct {
	ID, Parent string
	SubAgents  []SubAgentFiles
}

// ProjectsRoot returns the Claude Code projects directory:
// $CLAUDE_CONFIG_DIR/projects, else ~/.claude/projects.
func ProjectsRoot() (string, error) {
	if dir := os.Getenv("CLAUDE_CONFIG_DIR"); dir != "" {
		return filepath.Join(dir, "projects"), nil
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".claude", "projects"), nil
}

// LocateSession finds the sub-agent files of the session whose parent
// transcript is <dir>/<uuid>.jsonl, looking in <dir>/<uuid>/subagents/. A
// missing session directory means no sub-agents. Symbolic links are ignored
// and nothing is searched recursively.
func LocateSession(parentTranscript string) (SessionFiles, error) {
	base := filepath.Base(parentTranscript)
	if !strings.HasSuffix(base, transcriptExt) {
		return SessionFiles{}, fmt.Errorf("agentusage: %s does not end in %s", base, transcriptExt)
	}
	info, err := os.Lstat(parentTranscript)
	if err != nil {
		return SessionFiles{}, err
	}
	if !info.Mode().IsRegular() {
		return SessionFiles{}, fmt.Errorf("agentusage: %s is not a regular file", parentTranscript)
	}
	id := strings.TrimSuffix(base, transcriptExt)
	files := SessionFiles{ID: id, Parent: parentTranscript}
	sessionDir := filepath.Join(filepath.Dir(parentTranscript), id)
	if fi, err := os.Lstat(sessionDir); err != nil || !fi.IsDir() {
		if err == nil || errors.Is(err, os.ErrNotExist) {
			return files, nil // absent, or a link: no sub-agents
		}
		return files, err
	}
	files.SubAgents, err = subAgentFiles(filepath.Join(sessionDir, subagentsDir))
	return files, err
}

// subAgentFiles lists agent-<id>.jsonl files directly inside dir, sorted by
// ID, each with its meta file if one exists. A missing dir or a symbolic
// link yields nothing.
func subAgentFiles(dir string) ([]SubAgentFiles, error) {
	f, err := openPlain(dir, true)
	if f == nil {
		if err == nil || errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}
	defer func() { _ = f.Close() }()
	entries, err := f.ReadDir(-1)
	if err != nil {
		return nil, err
	}
	var out []SubAgentFiles
	for _, e := range entries {
		if sa, ok := subAgentEntry(dir, e); ok {
			out = append(out, sa)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out, nil
}

// subAgentEntry turns a directory entry into a sub-agent, if it is a
// regular agent-<id>.jsonl file.
func subAgentEntry(dir string, e os.DirEntry) (SubAgentFiles, bool) {
	name := e.Name()
	if !e.Type().IsRegular() || !strings.HasPrefix(name, agentPrefix) || !strings.HasSuffix(name, transcriptExt) {
		return SubAgentFiles{}, false
	}
	id := strings.TrimSuffix(strings.TrimPrefix(name, agentPrefix), transcriptExt)
	if id == "" {
		return SubAgentFiles{}, false
	}
	sa := SubAgentFiles{ID: id, Transcript: filepath.Join(dir, name)}
	metaPath := filepath.Join(dir, agentPrefix+id+metaExt)
	if mf, _ := openPlain(metaPath, false); mf != nil {
		_ = mf.Close()
		sa.Meta = metaPath
	}
	return sa, true
}
package agentusage

import (
	"encoding/json"
	"errors"
	"io"
)

// State tells whether a sub-agent has finished.
type State int

const (
	StateUnknown State = iota
	StateFinished
	StateUnfinished
)

// meta is the subset of agent-<id>.meta.json that is read. The description
// and worktree path keys are deliberately absent: they are never decoded.
type meta struct {
	AgentType  string
	Finished   *bool
	SpawnDepth int
}

// wireMeta keeps agentType and spawnDepth raw: one of an unexpected type
// costs that field only. finished stays typed, so a wrong type is an error.
type wireMeta struct {
	AgentType  json.RawMessage `json:"agentType"`
	Finished   *bool           `json:"finished"`
	SpawnDepth json.RawMessage `json:"spawnDepth"`
}

// maxMetaBytes is the largest meta file read; a bigger one is refused.
const maxMetaBytes = 1 << 20

// Fixed messages because encoding/json errors can quote file content.
var (
	errMalformedMeta = errors.New("agentusage: malformed meta file")
	errMetaTooBig    = errors.New("agentusage: meta file too large")
	errMetaNotPlain  = errors.New("agentusage: meta file is not a regular file")
)

// readMeta reads a meta file. A missing file yields an error satisfying
// errors.Is(err, os.ErrNotExist). A symbolic link or non-regular file is
// refused, and reading is bounded by maxMetaBytes.
func readMeta(path string) (meta, error) {
	f, err := openPlain(path, false)
	if err != nil {
		return meta{}, err
	}
	if f == nil {
		return meta{}, errMetaNotPlain
	}
	defer func() { _ = f.Close() }()
	b, err := io.ReadAll(io.LimitReader(f, maxMetaBytes+1))
	if err != nil {
		return meta{}, err
	}
	if len(b) > maxMetaBytes {
		return meta{}, errMetaTooBig
	}
	var w wireMeta
	if json.Unmarshal(b, &w) != nil {
		return meta{}, errMalformedMeta
	}
	m := meta{Finished: w.Finished, AgentType: optString(w.AgentType)}
	if len(w.SpawnDepth) > 0 {
		_ = json.Unmarshal(w.SpawnDepth, &m.SpawnDepth) // wrong type: stays 0
	}
	return m, nil
}

// state maps the finished flag; absent or null is StateUnknown.
func (m meta) state() State {
	switch {
	case m.Finished == nil:
		return StateUnknown
	case *m.Finished:
		return StateFinished
	}
	return StateUnfinished
}
package agentusage

import (
	"encoding/json"
	"strconv"
)

// lineKind classifies one transcript line.
type lineKind int

const (
	kindUsage      lineKind = iota // message.usage present: counts
	kindNoUsage                    // message present, no usage object
	kindIgnored                    // valid JSON without a message
	kindUnreadable                 // not JSON, truncated, or bad counters
	kindSynthetic                  // model "<synthetic>": never counts
)

// record is what decodeLine extracts from a line; only these fields are read.
type record struct {
	MessageID string
	Model     string
	Version   string
	Usage     Tokens
	StopNull  bool
}

// syntheticModel is the model name of locally generated, never-billed turns.
const syntheticModel = "<synthetic>"

// wireLine mirrors the only keys read from a transcript line. Content,
// tools and descriptions are deliberately not declared, so encoding/json
// skips them without keeping them. The root "type" key is not consulted.
type wireLine struct {
	Version json.RawMessage `json:"version"`
	Message *wireMessage    `json:"message"`
}

type wireMessage struct {
	ID         string          `json:"id"`
	Model      json.RawMessage `json:"model"`
	StopReason json.RawMessage `json:"stop_reason"`
	Usage      *wireUsage      `json:"usage"`
}

// wireUsage keeps counters raw so a negative, fractional or non-numeric
// value can be told apart from an absent one.
type wireUsage struct {
	Input      json.RawMessage `json:"input_tokens"`
	Output     json.RawMessage `json:"output_tokens"`
	CacheRead  json.RawMessage `json:"cache_read_input_tokens"`
	CacheWrite json.RawMessage `json:"cache_creation_input_tokens"`
}

// decodeLine extracts the usage fields of one transcript line. It never
// reports a decoder error: those can quote line content, so a bad line is
// just kindUnreadable.
func decodeLine(b []byte) (record, lineKind) {
	var w wireLine
	if err := json.Unmarshal(b, &w); err != nil {
		return record{}, kindUnreadable
	}
	m := w.Message
	if m == nil {
		return record{}, kindIgnored
	}
	rec := record{
		MessageID: m.ID,
		Model:     optString(m.Model),
		Version:   optString(w.Version),
		StopNull:  isNullOrAbsent(m.StopReason),
	}
	switch {
	case rec.Model == syntheticModel:
		return rec, kindSynthetic
	case m.Usage == nil:
		return rec, kindNoUsage
	}
	tokens, ok := m.Usage.tokens()
	if !ok {
		return record{}, kindUnreadable
	}
	rec.Usage = tokens
	return rec, kindUsage
}

// tokens converts the raw counters; ok is false if any is not a
// non-negative integer.
func (u *wireUsage) tokens() (Tokens, bool) {
	var t Tokens
	for _, c := range []struct {
		raw json.RawMessage
		dst *int64
	}{{u.Input, &t.Input}, {u.Output, &t.Output}, {u.CacheRead, &t.CacheRead}, {u.CacheWrite, &t.CacheWrite}} {
		n, ok := parseCounter(c.raw)
		if !ok {
			return Tokens{}, false
		}
		*c.dst = n
	}
	return t, true
}

// parseCounter reads one counter; absent or null is 0.
func parseCounter(raw json.RawMessage) (int64, bool) {
	if len(raw) == 0 || string(raw) == "null" {
		return 0, true
	}
	n, err := strconv.ParseInt(string(raw), 10, 64)
	return n, err == nil && n >= 0
}

// optString returns the JSON string held by raw, or "" if raw is absent or
// of another type: metadata of an unexpected type must not cost the line.
func optString(raw json.RawMessage) string {
	var s string
	if len(raw) == 0 || raw[0] != '"' || json.Unmarshal(raw, &s) != nil {
		return ""
	}
	return s
}

// isNullOrAbsent reports whether raw is a missing key or a JSON null. Any
// other value, whatever its type, counts as a stop reason being set.
func isNullOrAbsent(raw json.RawMessage) bool {
	return len(raw) == 0 || string(raw) == "null"
}
package agentusage

import (
	"bufio"
	"bytes"
	"errors"
	"io"
)

// readerBufferBytes is the bufio buffer size; longer lines are reassembled.
const readerBufferBytes = 64 << 10

// MaxLineBytes is the longest line (newline excluded) kept in memory.
const MaxLineBytes = 4 << 20

// scanResult describes what scanLines consumed.
type scanResult struct {
	// Consumed is the offset just past the last complete line.
	Consumed int64
	// Oversized counts complete lines longer than maxLen that were skipped.
	Oversized int
	// Tail holds the bytes after the last newline (an incomplete line).
	Tail []byte
}

// scanLines calls fn for every complete, non-empty line of r no longer
// than maxLen bytes. off is the offset of the line's first byte; line has no
// trailing "\n" or "\r" and is only valid during the call: fn must copy it
// to keep it. Complete lines longer than maxLen are skipped without being held
// in memory. An incomplete final line is returned in Tail whatever its
// length, unless it already exceeds maxLen: it is then dropped, and counted in
// neither Consumed nor Oversized (it may never be completed). A Tail of
// maxLen+1 or maxLen+2 bytes is still kept (the cutoff is maxLen+2, since a
// "\r" may follow); one longer than that is dropped.
func scanLines(r io.Reader, maxLen int, fn func(line []byte, off int64)) (scanResult, error) {
	br := bufio.NewReaderSize(r, readerBufferBytes)
	var (
		res      scanResult
		pending  []byte // line prefix reassembled across buffer fills
		skipping bool   // the current line is already known to be too long
		pos      int64  // bytes read so far
	)
	start := int64(0) // offset of the current line's first byte
	for {
		chunk, err := br.ReadSlice('\n')
		pos += int64(len(chunk))
		if !skipping {
			// maxLen+1 bytes are kept so a trailing "\r" does not count against maxLen.
			if len(pending)+len(chunk) > maxLen+2 { // +1 more: chunk may end with "\n"
				skipping, pending = true, nil
			} else {
				pending = append(pending, chunk...)
			}
		}
		switch {
		case err == nil:
			if skipping {
				res.Oversized++
			} else {
				res.emit(pending, start, maxLen, fn)
			}
			res.Consumed = pos
			start, pending, skipping = pos, pending[:0], false
		case errors.Is(err, bufio.ErrBufferFull):
		case errors.Is(err, io.EOF):
			if !skipping {
				res.Tail = bytes.Clone(pending)
			}
			return res, nil
		default:
			return res, err
		}
	}
}

// emit trims the line terminator from raw (which ends with "\n") and hands
// the line to fn, or counts it as oversized.
func (res *scanResult) emit(raw []byte, off int64, maxLen int, fn func([]byte, int64)) {
	line := bytes.TrimSuffix(bytes.TrimSuffix(raw, []byte("\n")), []byte("\r"))
	switch {
	case len(line) > maxLen:
		res.Oversized++
	case len(line) > 0:
		fn(line, off)
	}
}
package agentusage

import (
	"errors"
	"os"
)

// errNotPlain is returned when a path is not what Lstat said it was a moment
// ago (swapped for a link or another file). It is fixed so it never carries
// a path or content.
var errNotPlain = errors.New("agentusage: path changed while being opened")

// openPlain opens path only if it is not a symbolic link and its mode, as
// reported by Lstat, matches wantDir. The opened handle is compared with the
// Lstat result (os.SameFile), which closes the window between checking and
// opening. A missing path yields an error satisfying os.ErrNotExist; a path
// of the wrong kind yields (nil, nil).
func openPlain(path string, wantDir bool) (*os.File, error) {
	li, err := os.Lstat(path)
	if err != nil {
		return nil, err
	}
	if li.IsDir() != wantDir || (!wantDir && !li.Mode().IsRegular()) {
		return nil, nil
	}
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	fi, err := f.Stat()
	if err != nil || !os.SameFile(li, fi) {
		_ = f.Close()
		if err == nil {
			err = errNotPlain
		}
		return nil, err
	}
	return f, nil
}
// Package agentusage reads coding-agent usage logs. It is pure stdlib and
// has no dependency on the UI.
package agentusage

import "math"

// Tokens counts the tokens of one or more agent requests.
type Tokens struct {
	Input      int64
	Output     int64
	CacheRead  int64
	CacheWrite int64
}

// Total returns the sum of the four counters, saturating at math.MaxInt64.
func (t Tokens) Total() int64 {
	return satAdd(satAdd(t.Input, t.Output), satAdd(t.CacheRead, t.CacheWrite))
}

// Add returns the field-wise sum of t and o, each field saturating at
// math.MaxInt64.
func (t Tokens) Add(o Tokens) Tokens {
	return Tokens{
		Input:      satAdd(t.Input, o.Input),
		Output:     satAdd(t.Output, o.Output),
		CacheRead:  satAdd(t.CacheRead, o.CacheRead),
		CacheWrite: satAdd(t.CacheWrite, o.CacheWrite),
	}
}

// satAdd adds two non-negative counters without wrapping.
func satAdd(a, b int64) int64 {
	if a > math.MaxInt64-b {
		return math.MaxInt64
	}
	return a + b
}

